func:
// Recibe TODOS los mensajes SmartRack/# del ESP32.
//  - guarda el último valor de cada tópico (flow.estado, en memoria)
//  - arma el historial de temperatura/humedad (flow.historial, en disco)
//  - registra eventos: puerta, alarma, conexión, botón (flow.eventos, en disco)
const INTERVALO_MS = 10 * 1000;   // un punto de historial cada 10 s
const MAX_PUNTOS   = 8640;        // 24 h a 10 s
const MAX_EVENTOS  = 300;

const ahora    = Date.now();
const topico   = msg.topic;
const valor    = String(msg.payload).trim();
const retenido = msg.retain === true;   // retenido = valor viejo guardado en el broker

const estado = flow.get('estado') || { topicos: {}, datos: null, datosTs: null, ultimoMensaje: null };
const previo = estado.topicos[topico] ? estado.topicos[topico].valor : undefined;
estado.topicos[topico] = { valor: valor, ts: ahora, retenido: retenido };
if (!retenido) estado.ultimoMensaje = ahora;

function evento(tipo, texto, nivel) {
    const eventos = flow.get('eventos', 'disco') || [];
    eventos.push({ t: ahora, tipo: tipo, texto: texto, nivel: nivel || 'info' });
    if (eventos.length > MAX_EVENTOS) eventos.splice(0, eventos.length - MAX_EVENTOS);
    flow.set('eventos', eventos, 'disco');
}

// ---- JSON completo del ESP32 -> estado + historial
if (topico === 'SmartRack/Sensores/JSON') {
    let d = null;
    try { d = JSON.parse(valor); } catch (e) { node.warn('JSON inválido: ' + valor); }
    if (d && typeof d === 'object') {
        estado.datos = d;
        estado.datosTs = ahora;
        if (!retenido && d.dhtValido === true && typeof d.temperatura === 'number') {
            const hist = flow.get('historial', 'disco') || [];
            const ult = hist.length ? hist[hist.length - 1] : null;
            const a = d.alarma ? 1 : 0;
            const p = d.puerta === 'ABIERTA' ? 1 : 0;
            if (!ult || ahora - ult[0] >= INTERVALO_MS || ult[3] !== a || ult[4] !== p) {
                const hum = typeof d.humedad === 'number' ? d.humedad : null;
                hist.push([ahora, d.temperatura, hum, a, p]);
                const limite = ahora - 24 * 3600 * 1000;
                let quitar = 0;
                while (quitar < hist.length && hist[quitar][0] < limite) quitar++;
                if (hist.length - quitar > MAX_PUNTOS) quitar = hist.length - MAX_PUNTOS;
                if (quitar > 0) hist.splice(0, quitar);
                flow.set('historial', hist, 'disco');
            }
        }
    }
}

// ---- Eventos (solo mensajes en vivo y cuando el valor cambia;
//      la primera vez que llega un tópico no es un "cambio", salvo la conexión)
const ORIGEN = { BOTON_FISICO: 'el botón físico', MQTT: 'MQTT / dashboard' };
if (!retenido) {
    const cambio = previo !== valor && (previo !== undefined || topico === 'SmartRack/Estado/Conexion');
    if (cambio) {
        switch (topico) {
            case 'SmartRack/Sensores/Puerta':
                if (valor === 'ABIERTA') evento('puerta', 'Puerta abierta', 'aviso');
                else evento('puerta', 'Puerta cerrada', 'ok');
                break;
            case 'SmartRack/Alarmas/Estado':
                if (valor === 'ACTIVA') evento('alarma', 'Alarma activada: temperatura alta', 'critico');
                else evento('alarma', 'Alarma apagada', 'ok');
                break;
            case 'SmartRack/Estado/Conexion':
                if (valor === 'CONECTADO') evento('conexion', 'ESP32 conectado al broker', 'ok');
                else evento('conexion', 'ESP32 desconectado', 'critico');
                break;
            case 'SmartRack/Sensores/DHT11/Estado':
                if (valor === 'OK') evento('sensor', 'Sensor DHT11 leyendo de nuevo', 'ok');
                else evento('sensor', 'Sensor DHT11 sin lectura', 'aviso');
                break;
        }
    }
    if (topico === 'SmartRack/Alarmas/UltimoSilenciadoPor') {
        evento('alarma', 'Alarma silenciada desde ' + (ORIGEN[valor] || valor), 'info');
    }
    if (topico === 'SmartRack/Eventos/BotonFisico') {
        evento('boton', 'Botón físico presionado', 'info');
    }
}

flow.set('estado', estado);
return null;

// Guarda si Node-RED está conectado a Mosquitto (lo muestra el dashboard)
flow.set('mqttConectado', msg.status && msg.status.fill === 'green');
return null;

// GET /api/estado  ->  último estado conocido del rack
const est = flow.get('estado') || { topicos: {} };
const ahora = Date.now();
const v = (t) => est.topicos[t] ? est.topicos[t].valor : null;
const SIN_DATOS_MS = 15000;   // el ESP32 publica cada 2 s
const conexion = v('SmartRack/Estado/Conexion');
const recibiendo = !!est.ultimoMensaje && (ahora - est.ultimoMensaje) < SIN_DATOS_MS;

msg.payload = {
    servidor: { ts: ahora, mqttConectado: flow.get('mqttConectado') === true },
    esp32: {
        conexion: conexion,
        ip: v('SmartRack/Estado/IP'),
        enLinea: conexion === 'CONECTADO' && recibiendo,
        ultimoMensaje: est.ultimoMensaje || null
    },
    datos: est.datos || null,
    datosTs: est.datosTs || null,
    alarma: {
        estado: v('SmartRack/Alarmas/Estado'),
        ultimoSilenciadoPor: v('SmartRack/Alarmas/UltimoSilenciadoPor')
    },
    lcd: [v('SmartRack/Pantalla/Linea1'), v('SmartRack/Pantalla/Linea2')],
    topicos: est.topicos
};
msg.headers = { 'Cache-Control': 'no-store' };
return msg;

// GET /api/historial?horas=1  ->  puntos [t, temperatura, humedad, alarma, puertaAbierta]
const MAX_PUNTOS = 720;   // se promedian para no mandar miles de puntos al navegador
const hist = flow.get('historial', 'disco') || [];
let horas = parseFloat(msg.req.query.horas);
if (!isFinite(horas) || horas <= 0) horas = 1;
horas = Math.min(horas, 24);
const hasta = Date.now();
const desde = hasta - horas * 3600 * 1000;

let lo = 0, hi = hist.length;            // búsqueda binaria del primer punto >= desde
while (lo < hi) { const m = (lo + hi) >> 1; if (hist[m][0] < desde) lo = m + 1; else hi = m; }
let puntos = hist.slice(lo);

if (puntos.length > MAX_PUNTOS) {
    const paso = Math.ceil(puntos.length / MAX_PUNTOS);
    const r1 = (x) => Math.round(x * 10) / 10;
    const reducido = [];
    for (let i = 0; i < puntos.length; i += paso) {
        const g = puntos.slice(i, i + paso);
        let st = 0, nt = 0, sh = 0, nh = 0, a = 0, p = 0;
        for (const q of g) {
            if (typeof q[1] === 'number') { st += q[1]; nt++; }
            if (typeof q[2] === 'number') { sh += q[2]; nh++; }
            a = Math.max(a, q[3]); p = Math.max(p, q[4]);
        }
        reducido.push([g[0][0], nt ? r1(st / nt) : null, nh ? r1(sh / nh) : null, a, p]);
    }
    puntos = reducido;
}
msg.payload = { desde: desde, hasta: hasta, horas: horas,
                columnas: ['t', 'temperatura', 'humedad', 'alarma', 'puertaAbierta'], puntos: puntos };
msg.headers = { 'Cache-Control': 'no-store' };
return msg;

// GET /api/historial.csv?horas=24  ->  descarga CSV (hora local del servidor)
const hist = flow.get('historial', 'disco') || [];
let horas = parseFloat(msg.req.query.horas);
if (!isFinite(horas) || horas <= 0) horas = 24;
const desde = Date.now() - Math.min(horas, 24) * 3600 * 1000;
const dos = (n) => String(n).padStart(2, '0');
const fecha = (t) => { const d = new Date(t);
    return d.getFullYear() + '-' + dos(d.getMonth() + 1) + '-' + dos(d.getDate()) + ' ' +
           dos(d.getHours()) + ':' + dos(d.getMinutes()) + ':' + dos(d.getSeconds()); };
const lineas = ['fecha_hora,temperatura_c,humedad_pct,alarma_activa,puerta_abierta'];
for (const p of hist) {
    if (p[0] < desde) continue;
    lineas.push([fecha(p[0]), p[1] ?? '', p[2] ?? '', p[3], p[4]].join(','));
}
const ahora = new Date();
const nombre = 'smartrack_' + ahora.getFullYear() + dos(ahora.getMonth() + 1) + dos(ahora.getDate()) +
               '_' + dos(ahora.getHours()) + dos(ahora.getMinutes()) + '.csv';
msg.payload = lineas.join('\n') + '\n';
msg.headers = { 'Content-Type': 'text/csv; charset=utf-8',
                'Content-Disposition': 'attachment; filename="' + nombre + '"',
                'Cache-Control': 'no-store' };
return msg;

// GET /api/eventos  ->  últimos 100 eventos, el más reciente primero
const eventos = flow.get('eventos', 'disco') || [];
msg.payload = eventos.slice(-100).reverse();
msg.headers = { 'Cache-Control': 'no-store' };
return msg;

// POST /api/alarma/apagar  ->  publica APAGAR en SmartRack/Control/Alarma
// La cabecera X-SmartRack evita que otra página web dispare la orden (CSRF).
if (msg.req.headers['x-smartrack'] !== '1') {
    msg.statusCode = 403;
    msg.payload = { ok: false, error: 'Falta la cabecera X-SmartRack' };
    return [null, msg];
}
const usuario = msg.req.headers['x-usuario'] || 'dashboard';
const eventos = flow.get('eventos', 'disco') || [];
eventos.push({ t: Date.now(), tipo: 'alarma', texto: 'Orden APAGAR enviada desde el dashboard (' + usuario + ')', nivel: 'info' });
if (eventos.length > 300) eventos.splice(0, eventos.length - 300);
flow.set('eventos', eventos, 'disco');

const orden = { payload: 'APAGAR' };
msg.payload = { ok: true, enviado: 'APAGAR', mqttConectado: flow.get('mqttConectado') === true };
msg.headers = { 'Cache-Control': 'no-store' };
return [orden, msg];
